export interface LineItem {
  readonly cents: number;
  readonly quantity: number;
}

interface SubtotalCalculator {
  compute(items: readonly LineItem[]): number;
}

interface SubtotalDto {
  readonly rawCents: number;
}

class DefaultSubtotalCalculator implements SubtotalCalculator {
  compute(items: readonly LineItem[]): number {
    let sum = 0;
    for (const item of items) sum += item.cents * item.quantity;
    return sum;
  }
}

function toSubtotalDto(rawCents: number): SubtotalDto {
  return { rawCents };
}

export function orderTotalCents(items: readonly LineItem[], taxBps: number): number {
  const calculator: SubtotalCalculator = new DefaultSubtotalCalculator();
  const dto = toSubtotalDto(calculator.compute(items));
  return dto.rawCents + Math.round((dto.rawCents * taxBps) / 10_000);
}

