import { useEffect, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useProjectStore, type ProjectSummary } from "./projectStore";

async function fetchProjects(teamId: string): Promise<readonly ProjectSummary[]> {
  const res = await fetch(`/api/teams/${encodeURIComponent(teamId)}/projects`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return (await res.json()) as readonly ProjectSummary[];
}

export function ProjectList({ teamId }: { readonly teamId: string }) {
  const { data } = useQuery({
    queryKey: ["projects", teamId],
    queryFn: () => fetchProjects(teamId),
  });
  const { projects, setProjects, isHelpOpen, setHelpOpen } = useProjectStore();
  const [count, setCount] = useState(0);

  useEffect(() => {
    if (data) {
      setProjects(data);
      setCount(data.length);
    }
  }, [data, setProjects]);

  return (
    <section>
      <header>
        <h2>Projects ({count})</h2>
        <button type="button" onClick={() => setHelpOpen(!isHelpOpen)}>Help</button>
      </header>
      {isHelpOpen && <p>Select a project to inspect deployments.</p>}
      <ul>
        {projects.map((p) => <li key={p.id}>{p.name}</li>)}
      </ul>
    </section>
  );
}

