import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";

export interface ProjectDetail {
  readonly id: string;
  readonly name: string;
}

export function ProjectNameForm({ project }: { readonly project: ProjectDetail }) {
  const [draftName, setDraftName] = useState(project.name);
  const queryClient = useQueryClient();
  const rename = useMutation({
    mutationFn: async (nextName: string) => {
      const res = await fetch(`/api/projects/${encodeURIComponent(project.id)}`, {
        method: "PATCH",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ name: nextName }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["projects", project.id] }),
  });

  return (
    <form onSubmit={(e) => { e.preventDefault(); rename.mutate(draftName); }}>
      <input value={draftName} onChange={(e) => setDraftName(e.currentTarget.value)} />
      <button type="submit" disabled={rename.isPending}>Save</button>
    </form>
  );
}

