export function InvitePanel({ members, onInvite }: {
  readonly members: readonly string[];
  readonly onInvite: (email: string) => Promise<void>;
}) {
  const [email, setEmail] = useState("");
  const [shouldSubmit, setShouldSubmit] = useState(false);
  const [status, setStatus] = useState<"idle" | "sent">("idle");

  function MemberBadge({ address }: { readonly address: string }) {
    return <li className="member-pill">{address} ({email === address ? "duplicate" : "active"})</li>;
  }

  useEffect(() => {
    if (!shouldSubmit) return;
    setShouldSubmit(false);
    void onInvite(email).then(() => {
      setEmail("");
      setStatus("sent");
    });
  }, [shouldSubmit, email, onInvite]);

  return (
    <div>
      <input value={email} onChange={(e) => setEmail(e.currentTarget.value)} />
      <button type="button" onClick={() => setShouldSubmit(true)}>Send invite</button>
      {status === "sent" && <span>Invitation sent</span>}
      <ul>{members.map((m) => <MemberBadge key={m} address={m} />)}</ul>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

function MemberBadge({ address, isDuplicate }: { readonly address: string; readonly isDuplicate: boolean }) {
  return <li className="member-pill">{address} ({isDuplicate ? "duplicate" : "active"})</li>;
}

export function InvitePanel({ members, onInvite }: {
  readonly members: readonly string[];
  readonly onInvite: (email: string) => Promise<void>;
}) {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<"idle" | "sent">("idle");
  const [widthPx, setWidthPx] = useState(0);
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const node = panelRef.current;
    if (!node) return;
    const observer = new ResizeObserver(([entry]) => {
      if (entry) setWidthPx(Math.round(entry.contentRect.width));
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  async function handleSend() {
    await onInvite(email);
    setEmail("");
    setStatus("sent");
  }

  return (
    <div ref={panelRef} data-compact={widthPx > 0 && widthPx < 420}>
      <input value={email} onChange={(e) => setEmail(e.currentTarget.value)} />
      <button type="button" onClick={() => void handleSend()}>Send invite</button>
      {status === "sent" && <span>Invitation sent</span>}
      <ul>{members.map((m) => <MemberBadge key={m} address={m} isDuplicate={email === m} />)}</ul>
    </div>
  );
}

