import { useEffect } from "react";

export type ThemeName = "light" | "dark" | "system";

export function ThemePicker({ themes, onSelect }: {
  readonly themes: readonly ThemeName[];
  readonly onSelect: (theme: ThemeName) => void;
}) {
  useEffect(() => {
    if (typeof window === "undefined") return;
    window.localStorage.setItem("theme-picker-opened", "1");
  }, []);

  const safeThemes = Array.isArray(themes) ? themes : [];

  function handlePick(theme: ThemeName) {
    if (typeof window === "undefined") return;
    window.localStorage.setItem("preferred-theme", theme);
    onSelect?.(theme);
  }

  return (
    <div>
      {safeThemes.map((t) => (
        <button key={t} type="button" onClick={() => handlePick(t)}>{t}</button>
      ))}
    </div>
  );
}

