import { useState } from "react";

export function CouponForm() {
  const [code, setCode] = useState("");
  const [tags, setTags] = useState<string[]>(["vip"]);
  const [maxRedemptions, setMaxRedemptions] = useState<number | null>(null);
  const [status, setStatus] = useState<"idle" | "saving" | "saved" | "error">("idle");

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (status === "saving") return;
    setStatus("saving");
    try {
      const res = await fetch("/api/coupons", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ code, tags, maxRedemptions }),
      });
      if (!res.ok) {
        setStatus("error");
        return;
      }
      setStatus("saved");
    } catch {
      setStatus("error");
    }
  }

  return (
    <form onSubmit={(e) => void handleSubmit(e)}>
      <input value={code} onChange={(e) => setCode(e.currentTarget.value)} />
      <input
        type="number"
        value={maxRedemptions ?? ""}
        onChange={(e) => {
          const raw = e.currentTarget.value.trim();
          if (raw === "") { setMaxRedemptions(null); return; }
          const parsed = Number(raw);
          if (Number.isInteger(parsed) && parsed > 0) setMaxRedemptions(parsed);
        }}
      />
      {tags.map((tag) => (
        <span key={tag}>
          {tag}
          <button type="button" onClick={() => setTags((prev) => prev.filter((t) => t !== tag))}>Remove</button>
        </span>
      ))}
      <button type="submit" disabled={status === "saving"}>Create coupon</button>
      {status === "saved" && <p role="status">Coupon created</p>}
      {status === "error" && <p role="alert">Could not save coupon</p>}
    </form>
  );
}

