"use client";
import { useEffect, useState } from "react";

export function WorkspaceMetrics({ workspaceId }: { readonly workspaceId: string }) {
  const [state, setState] = useState<{ workspaceId: string; totalEvents: number } | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    void fetch(`/api/workspaces/${encodeURIComponent(workspaceId)}/metrics`, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json() as Promise<{ totalEvents: number }>;
      })
      .then((payload) => {
        if (!controller.signal.aborted) setState({ workspaceId, totalEvents: payload.totalEvents });
      })
      .catch(() => {});
    return () => controller.abort();
  }, [workspaceId]);

  const current = state?.workspaceId === workspaceId ? state.totalEvents : null;
  return <div>Events: {current ?? "Loading..."}</div>;
}

