export interface FullOrderRecord {
  readonly id: string;
  readonly title: string;
  readonly rawInvoiceHtml: string;
  readonly auditLogEntries: readonly string[];
}

export function OrderScroller({ orders }: { readonly orders: readonly FullOrderRecord[] }) {
  const rowRefs = useRef<Array<HTMLDivElement | null>>([]);

  function handleScroll(e: React.UIEvent<HTMLDivElement>) {
    const scrollTop = e.currentTarget.scrollTop;
    for (const el of rowRefs.current) {
      if (!el) continue;
      const height = el.getBoundingClientRect().height;
      el.style.opacity = height + scrollTop > 0 ? "1" : "0.5";
    }
  }

  return (
    <div onScroll={handleScroll} style={{ height: 600, overflowY: "auto" }}>
      {orders.map((order, idx) => (
        <div key={order.id} ref={(el) => { rowRefs.current[idx] = el; }}>{order.title}</div>
      ))}
    </div>
  );
}

